package main

import (
	"fmt"
	"runtime"
	"time"
)

func main() {
	done := make(chan bool)
	for i := 1; i <= 3; i++ {
		go func() {
			for {
				select {
				case <-done:
					fmt.Println("worker", i, "stopping")
					return
				default:
					time.Sleep(10 * time.Millisecond)
				}
			}
		}()
	}
	time.Sleep(50 * time.Millisecond)
	done <- true
	time.Sleep(100 * time.Millisecond)
	fmt.Println("goroutines:", runtime.NumGoroutine())
}
